cases.script:
cu() { if [[ $(type -t coreutils) == builtin ]]; then coreutils "$@"; else "$@"; fi; }
shopt -s extglob
r() { local rc=0 line; "$@" >out 2>err || rc=$?; cat out; while IFS= read -r line; do line=${line#fixture: line +([0-9]): }; printf "%s\n" "$line"; done < err; echo "rc=$rc"; }
printf 'l1\nl2\n' > in
r cu shuf --random-source=/dev/null -e a b; r cu shuf --rand /nonexist in; r cu shuf -e a -o /nonexist/x; r cu shuf -i 1-3 extra; r cu shuf -ie; r cu shuf --input-range; r cu shuf -i a-b; r cu shuf -n -1 in; r cu shuf -n 18446744073709551616 -e x; r cu shuf -i 0-18446744073709551615 -n 0; r cu shuf -n 1 -n 0 -e x; r cu shuf -i 5-4; r cu shuf -r -n 0 </dev/null; r cu shuf -r -n 3 -i 7-7; r cu shuf -z -e q | od -c; r cu shuf nosuch; r cu shuf --output
